H,W=len(G),len(G[0])
sixes=[(i,j) for i in range(H) for j in range(W) if G[i][j]==6]
# template: vertical 8,3,0 centered at 3 -> offsets -1..1
out=[row[:] for row in G]
conf=[]
for (r,c) in sixes:
    for k,v in ((-1,8),(0,3),(1,0)):
        rr=r+k
        if 0<=rr<H:
            if out[rr][c] not in (1,6,8,3,0) : conf.append((rr,c,out[rr][c]))
            out[rr][c]=v
print("conflicts:",conf)
# check no two 6s vertically adjacent
bad=[(a,b) for a in sixes for b in sixes if a!=b and abs(a[0]-b[0])<=1 and a[1]==b[1]]
print("adjacent 6s:",bad)
for row in out: print(' '.join(map(str,row)))
